package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="ingreso_residuo") public class IngresoResiduo { @Id @GeneratedValue private UUID id; @Column(name="recoleccion_externa_id") private UUID recoleccionExternaId; @ManyToOne(optional=false) @JoinColumn(name="tipo_residuo_id") private TipoResiduo tipoResiduo; @Column(name="recibido_por_usuario_externo_id",nullable=false) private UUID responsableId; @Column(name="fecha_hora_recepcion",nullable=false) private OffsetDateTime fechaHora; @Column(name="peso_kg",nullable=false) private BigDecimal pesoKg; private String observacion; public UUID getId(){return id;} public TipoResiduo getTipoResiduo(){return tipoResiduo;} public UUID getResponsableId(){return responsableId;} public OffsetDateTime getFechaHora(){return fechaHora;} public BigDecimal getPesoKg(){return pesoKg;} public String getObservacion(){return observacion;} public void cargar(UUID rec,TipoResiduo tipo,UUID resp,OffsetDateTime fecha,BigDecimal peso,String obs){recoleccionExternaId=rec;tipoResiduo=tipo;responsableId=resp;fechaHora=fecha;pesoKg=peso;observacion=obs;} }
